package com.acme.payments.transfer;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.util.List;
import java.util.Objects;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Creates, settles and cancels transfers between accounts. Funds are
 * reserved on the source account when a transfer is created and either
 * booked on settlement or released on cancellation.
 */
@Service
public class TransferService {

    private static final Logger log = LoggerFactory.getLogger(TransferService.class);

    public enum Status { PENDING, SETTLED, CANCELLED }

    public record Transfer(
            Long id,
            Long sourceAccountId,
            Long targetAccountId,
            BigDecimal amount,
            Status status,
            Instant updatedAt) {

        Transfer withStatus(Status next, Instant at) {
            return new Transfer(id, sourceAccountId, targetAccountId, amount, next, at);
        }
    }

    private final TransferRepository transfers;
    private final LedgerClient ledger;
    private final Clock clock;

    public TransferService(TransferRepository transfers, LedgerClient ledger, Clock clock) {
        this.transfers = Objects.requireNonNull(transfers, "transfers");
        this.ledger = Objects.requireNonNull(ledger, "ledger");
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    @Transactional
    public Transfer create(Long sourceAccountId, Long targetAccountId, BigDecimal amount) {
        Objects.requireNonNull(sourceAccountId, "sourceAccountId");
        Objects.requireNonNull(targetAccountId, "targetAccountId");
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        if (sourceAccountId.equals(targetAccountId)) {
            throw new IllegalArgumentException("source and target account must differ");
        }
        Transfer saved = transfers.save(new Transfer(
                null, sourceAccountId, targetAccountId, amount, Status.PENDING, clock.instant()));
        ledger.reserve(sourceAccountId, amount, saved.id());
        log.info("created transfer {} from account {} to account {}",
                saved.id(), sourceAccountId, targetAccountId);
        return saved;
    }

    @Transactional(readOnly = true)
    public List<Transfer> pendingFor(Long accountId) {
        Objects.requireNonNull(accountId, "accountId");
        return transfers.findBySourceAccountIdAndStatus(accountId, Status.PENDING);
    }

    /**
     * Books a pending transfer. Called by the settlement job only; the row is
     * locked so a concurrent cancellation waits for the outcome.
     */
    @Transactional
    public Transfer settle(Long transferId) {
        Objects.requireNonNull(transferId, "transferId");
        Transfer transfer = transfers.findByIdForUpdate(transferId)
                .orElseThrow(() -> new TransferNotFoundException(transferId));
        if (transfer.status() != Status.PENDING) {
            throw new IllegalStateException(
                    "transfer " + transferId + " is " + transfer.status() + " and cannot be settled");
        }
        Transfer settled = transfers.save(transfer.withStatus(Status.SETTLED, clock.instant()));
        ledger.book(transfer.sourceAccountId(), transfer.targetAccountId(), transfer.amount(), transferId);
        log.info("settled transfer {}", transferId);
        return settled;
    }

    /**
     * Cancels a pending transfer on behalf of the account that created it and
     * releases the reserved funds. Only the source account may cancel.
     */
    @Transactional
    public Transfer cancel(Long transferId, Long requesterAccountId) {
        Objects.requireNonNull(transferId, "transferId");
        Objects.requireNonNull(requesterAccountId, "requesterAccountId");
        Transfer transfer = transfers.findByIdForUpdate(transferId)
                .orElseThrow(() -> new TransferNotFoundException(transferId));
        if (transfer.sourceAccountId() != requesterAccountId) {
            throw new TransferAccessDeniedException(transferId, requesterAccountId);
        }
        if (transfer.status() != Status.PENDING) {
            throw new IllegalStateException(
                    "transfer " + transferId + " is " + transfer.status() + " and cannot be cancelled");
        }
        Transfer cancelled = transfers.save(transfer.withStatus(Status.CANCELLED, clock.instant()));
        ledger.release(transfer.sourceAccountId(), transfer.amount(), transferId);
        log.info("cancelled transfer {} for account {}", transferId, requesterAccountId);
        return cancelled;
    }
}
